CREATE TABLE IF NOT EXISTS service_metadata(app_key TEXT PRIMARY KEY CHECK(app_key='melodiajest'),schema_version INTEGER NOT NULL CHECK(schema_version=2));
INSERT INTO service_metadata(app_key,schema_version) VALUES('melodiajest',2) ON CONFLICT(app_key) DO NOTHING;
CREATE TABLE IF NOT EXISTS learning_preferences(user_id TEXT PRIMARY KEY REFERENCES users(id),course_mode TEXT NOT NULL DEFAULT 'sequential' CHECK(course_mode IN ('sequential','free')),rating_system TEXT NOT NULL DEFAULT 'ten' CHECK(rating_system IN ('ten','ten_decimal','hundred','five','three','two')),revision INTEGER NOT NULL DEFAULT 1,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS learning_attempts(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id),lesson_id TEXT NOT NULL,music_version TEXT NOT NULL,edition_version TEXT NOT NULL,goal_key TEXT NOT NULL,policy_version INTEGER NOT NULL,mode TEXT NOT NULL CHECK(mode IN ('challenge','memory')),bpm INTEGER NOT NULL,nonce_hash TEXT NOT NULL,started_at INTEGER NOT NULL,expires_at INTEGER NOT NULL,submitted_at INTEGER,request_digest TEXT,result_raw TEXT,events_raw TEXT,status TEXT NOT NULL CHECK(status IN ('issued','passed','failed')),awarded_xp INTEGER NOT NULL DEFAULT 0 CHECK(awarded_xp>=0 AND awarded_xp<=100));
CREATE INDEX IF NOT EXISTS learning_attempts_owner ON learning_attempts(owner_id,started_at,id);
CREATE TABLE IF NOT EXISTS lesson_progress(owner_id TEXT NOT NULL REFERENCES users(id),lesson_id TEXT NOT NULL,music_version TEXT NOT NULL,first_passed_at INTEGER NOT NULL,best_quality INTEGER NOT NULL CHECK(best_quality>=0 AND best_quality<=100),clean_attempts INTEGER NOT NULL,memory_passed_at INTEGER,updated_at INTEGER NOT NULL,PRIMARY KEY(owner_id,lesson_id,music_version));
CREATE TABLE IF NOT EXISTS goal_experience(owner_id TEXT NOT NULL REFERENCES users(id),goal_key TEXT NOT NULL,policy_version INTEGER NOT NULL,best_xp INTEGER NOT NULL CHECK(best_xp>=0 AND best_xp<=100),updated_at INTEGER NOT NULL,PRIMARY KEY(owner_id,goal_key,policy_version));
CREATE TABLE IF NOT EXISTS experience_events(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id),attempt_id TEXT NOT NULL UNIQUE REFERENCES learning_attempts(id),goal_key TEXT NOT NULL,delta INTEGER NOT NULL CHECK(delta>0 AND delta<=100),created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS experience_events_owner ON experience_events(owner_id,created_at,id);
CREATE TABLE IF NOT EXISTS portal_experience_outbox(owner_id TEXT NOT NULL REFERENCES users(id),goal_key TEXT NOT NULL,policy_version INTEGER NOT NULL,best_xp INTEGER NOT NULL CHECK(best_xp>=0 AND best_xp<=100),revision INTEGER NOT NULL,delivered_revision INTEGER NOT NULL DEFAULT 0,updated_at INTEGER NOT NULL,PRIMARY KEY(owner_id,goal_key,policy_version));
CREATE TABLE IF NOT EXISTS portal_level_cache(owner_id TEXT PRIMARY KEY REFERENCES users(id),issuer TEXT NOT NULL,subject TEXT NOT NULL,total_xp INTEGER NOT NULL CHECK(total_xp>=0),level INTEGER NOT NULL CHECK(level>=1),checked_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS lesson_ratings(owner_id TEXT NOT NULL REFERENCES users(id),lesson_id TEXT NOT NULL,edition_version TEXT NOT NULL,system TEXT NOT NULL,raw_value TEXT NOT NULL,canonical_units INTEGER NOT NULL CHECK(canonical_units>=0 AND canonical_units<=10000),revision INTEGER NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)),PRIMARY KEY(owner_id,lesson_id,edition_version));
CREATE INDEX IF NOT EXISTS lesson_ratings_public ON lesson_ratings(lesson_id,edition_version);
CREATE TABLE IF NOT EXISTS lesson_rating_revisions(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id),lesson_id TEXT NOT NULL,edition_version TEXT NOT NULL,raw_value TEXT,canonical_units INTEGER,revision INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS discussion_comments(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES users(id),scope TEXT NOT NULL CHECK(scope IN ('global','lesson')),lesson_id TEXT NOT NULL,edition_version TEXT,parent_id TEXT REFERENCES discussion_comments(id),body TEXT NOT NULL,revision INTEGER NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,deleted INTEGER NOT NULL DEFAULT 0 CHECK(deleted IN (0,1)),CHECK((scope='global' AND lesson_id='') OR (scope='lesson' AND length(lesson_id)>0)));
CREATE INDEX IF NOT EXISTS discussion_comments_scope ON discussion_comments(scope,lesson_id,created_at,id);
CREATE TABLE IF NOT EXISTS discussion_comment_revisions(id TEXT PRIMARY KEY,comment_id TEXT NOT NULL REFERENCES discussion_comments(id),owner_id TEXT NOT NULL REFERENCES users(id),body TEXT NOT NULL,revision INTEGER NOT NULL,deleted INTEGER NOT NULL CHECK(deleted IN (0,1)),created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS course_editions(lesson_id TEXT NOT NULL,music_version TEXT NOT NULL,edition_version TEXT NOT NULL,plan_raw TEXT NOT NULL,PRIMARY KEY(lesson_id,music_version,edition_version));
CREATE TABLE IF NOT EXISTS game_operation_receipts(owner_id TEXT NOT NULL REFERENCES users(id),operation_id TEXT NOT NULL,kind TEXT NOT NULL,digest TEXT NOT NULL,response_raw TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(owner_id,operation_id));
